def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    src=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2][0]
    # initial direction: into the grid
    r0,c0=src; dirs=[]
    if r0==0: dirs.append((1,0))
    if r0==h-1: dirs.append((-1,0))
    if c0==0: dirs.append((0,1))
    if c0==w-1: dirs.append((0,-1))
    if not dirs: dirs=[(1,0)]
    def paint(r,c):
        if 0<=r<h and 0<=c<w and out[r][c]!=2: out[r][c]=2
    def step(d): return (d[0],d[1])
    def beam(r,c,d,seen):
        if (r,c,d) in seen: return
        seen.add((r,c,d)); paint(r,c)
        nr,nc=r+d[0],c+d[1]
        if not(0<=nr<h and 0<=nc<w): return
        if g[nr][nc]==8:
            # sweep perpendicular, resume original dir d through gaps
            if d[0]==0: perp=[(1,0),(-1,0)]
            else: perp=[(0,1),(0,-1)]
            for p in perp:
                rr,cc=r,c
                while True:
                    rr,cc=rr+p[0],cc+p[1]
                    if not(0<=rr<h and 0<=cc<w): break
                    paint(rr,cc)
                    gr,gc=rr+d[0],cc+d[1]
                    if 0<=gr<h and 0<=gc<w and g[gr][gc]!=8:
                        beam(rr,cc,d,seen); break
        else:
            beam(nr,nc,d,seen)
    seen=set()
    for d in dirs: beam(r0,c0,d,seen)
    return out
